import emojiData from './emojiData.json';

// An emoji, or [emoji, variant, variant...] when it has skin-tone (or
// other) variants - the first item is the one shown in the grid.
export type EmojiEntry = string | string[];

export interface EmojiCategory {
  id: string;
  // A MaterialIcons glyph name (see EmojiPanel's category tabs) rather
  // than an emoji character, matching Gboard's monochrome category icons.
  icon: string;
  emojis: EmojiEntry[];
}

// Every emoji in Unicode's current emoji list, in its order - generated by
// scripts/generate-emoji-data.py (see there to update it). Which of them
// the phone can draw is worked out at run time: EmojiSupportModule.
export const EMOJI_CATEGORIES: EmojiCategory[] = emojiData as EmojiCategory[];
